// ============================================
// ПАРСЕР ВХОДЯЩЕГО СООБЩЕНИЯ ИЗ TELEGRAM
// ============================================
// Поддерживаемые форматы:
// 1. Структурированный (Биржа: ... Ссылка: ... и т.д.)
// 2. Свободный текст (AI разберёт)

const message = $input.first().json.message.text || '';
const chatId = $input.first().json.message.chat.id;
const username = $input.first().json.message.from.username || 'unknown';

// Попытка структурированного парсинга
function parseStructured(text) {
  const fields = {};

  const patterns = {
    platform: /(?:Биржа|Площадка|Платформа)[:\s]+(.+)/i,
    link: /(?:Ссылка|URL|Link)[:\s]+(https?:\/\/[^\s]+)/i,
    title: /(?:Заголовок|Название|Тема)[:\s]+(.+)/i,
    description: /(?:Описание|Задача|ТЗ|Текст)[:\s]+([\s\S]*?)(?=(?:Бюджет|Дедлайн|Срок|$))/i,
    budget: /(?:Бюджет|Цена|Стоимость|Оплата)[:\s]+(.+)/i,
    deadline: /(?:Дедлайн|Срок|Время|Когда)[:\s]+(.+)/i
  };

  for (const [key, regex] of Object.entries(patterns)) {
    const match = text.match(regex);
    if (match) {
      fields[key] = match[1].trim();
    }
  }

  return fields;
}

// Определение биржи по ссылке
function detectPlatform(text) {
  const platforms = {
    'kwork.ru': 'Kwork',
    'fl.ru': 'FL.ru',
    'freelance.habr.com': 'Habr Freelance',
    'linkedin.com': 'LinkedIn',
    'profi.ru': 'Profi.ru',
    'youdo.com': 'YouDo',
    'freelansim.ru': 'Freelansim',
    'weblancer.net': 'Weblancer',
    'freelance.ru': 'Freelance.ru',
    'upwork.com': 'Upwork',
    'fiverr.com': 'Fiverr',
    't.me': 'Telegram',
    'telegram': 'Telegram'
  };

  for (const [domain, name] of Object.entries(platforms)) {
    if (text.toLowerCase().includes(domain)) {
      return name;
    }
  }
  return 'Не определена';
}

// Определение команды
const isCommand = message.startsWith('/');
let command = null;
if (isCommand) {
  command = message.split(' ')[0].toLowerCase();
}

const parsed = parseStructured(message);
const detectedPlatform = parsed.platform || detectPlatform(message);

// Проверка: структурированный или свободный формат
const isStructured = Object.keys(parsed).length >= 2;

return [{
  json: {
    chatId,
    username,
    rawMessage: message,
    isCommand,
    command,
    isStructured,
    platform: detectedPlatform,
    link: parsed.link || '',
    title: parsed.title || '',
    description: parsed.description || message,
    budget: parsed.budget || 'Не указан',
    deadline: parsed.deadline || 'Не указан',
    timestamp: new Date().toISOString()
  }
}];

